diff --git a/src/lib/OpenEXRCore/parse_header.c b/src/lib/OpenEXRCore/parse_header.c
index af0fd25..e7f4eef 100644
--- a/src/lib/OpenEXRCore/parse_header.c
+++ b/src/lib/OpenEXRCore/parse_header.c
@@ -348,6 +348,22 @@ read_text (

 /**************************************/

+static int32_t
+name_length_limit (exr_context_t ctxt)
+{
+    int32_t limit;
+
+    if (ctxt->strict_header) return (int32_t) ctxt->max_name_length;
+
+    /* Non-strict readers accept a name as long as the context can record
+     * its length, and at least the spec long-name maximum. */
+    limit = (int32_t) ((1u << (int) (sizeof (ctxt->max_name_length) * 8)) - 1u);
+    if (EXR_LONGNAME_MAXLEN > limit) limit = EXR_LONGNAME_MAXLEN;
+    return limit;
+}
+
+/**************************************/
+
 static exr_result_t
 extract_attr_chlist (
     exr_context_t                     ctxt,
@@ -361,7 +377,7 @@ extract_attr_chlist (
     int32_t      chlen;
     int32_t      ptype, xsamp, ysamp;
     uint8_t      flags[4];
-    int32_t      maxlen = ctxt->max_name_length;
+    int32_t      maxlen = name_length_limit (ctxt);
     exr_result_t rv;

     rv = check_bad_attrsz (scratch, attrsz, 1, aname, tname, &chlen);
@@ -2049,7 +2065,7 @@ pull_attr (
     int32_t          attrsz = 0;
     exr_attribute_t* nattr  = NULL;
     uint8_t*         strptr = NULL;
-    const int32_t    maxlen = ctxt->max_name_length;
+    const int32_t    maxlen = name_length_limit (ctxt);

     name[0] = (char) init_byte;
     namelen = 1;

